export const POOL=Object.keys(CARDS).filter(k=>!CARDS[k].starter);
export const STAGES=[{type:'battle',name:'外围巡逻',enemy:'scout'},{type:'event',name:'失落缓存'},{type:'battle',name:'静默哨站',enemy:'sentry'},{type:'camp',name:'中继营地'},{type:'battle',name:'禁区守卫',enemy:'elite'},{type:'event',name:'最后的信号'},{type:'battle',name:'余烬之心',enemy:'boss'}];
const ENEMIES={scout:{name:'巡游机',maxHp:32,art:'scout',intents:[{type:'attack',value:7},{type:'guard',value:6},{type:'attack',value:10}]},sentry:{name:'棱镜哨兵',maxHp:46,art:'sentry',intents:[{type:'attack',value:9},{type:'attack',value:5,hits:2},{type:'buff',value:2}]},elite:{name:'裂隙守卫',maxHp:67,art:'elite',intents:[{type:'attack',value:12},{type:'guard',value:10},{type:'attack',value:7,hits:2},{type:'buff',value:2}]},boss:{name:'失序核心',maxHp:98,art:'boss',intents:[{type:'attack',value:12},{type:'attack',value:7,hits:2},{type:'buff',value:3},{type:'attack',value:20}]}};
export function hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function rnd(r){r.rng=(r.rng+0x6D2B79F5)>>>0;let t=r.rng;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;}
function shuffle(r,a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(rnd(r)*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
export function cardData(c){const b=CARDS[c.id];return {...b,...(c.up?b.up:{}),id:c.id,up:!!c.up};}
export function cardText(c){const d=cardData(c);return d.text.replace(/\{(\w+)\}/g,(_,k)=>d[k]);}
export function log(r,text,kind='info'){r.log.push({text,kind});if(r.log.length>40)r.log.shift();}
function track(r,type,data={}){r.events.push({type,...data,at:Date.now()-r.startedAt,stage:r.stage+1});}
function draw(r,n){for(let i=0;i<n;i++){if(!r.draw.length&&r.discard.length){r.draw=shuffle(r,r.discard);r.discard=[];}if(!r.draw.length||r.hand.length>=10)break;r.hand.push(r.draw.pop());}}
export function intent(r){return r.enemy?.intents[r.enemy.step%r.enemy.intents.length];}
export function createRun({seed='EMBER-01',mode='choice'}={}){if(!['choice','random'].includes(mode))throw new Error('Invalid mode');seed=String(seed).trim().slice(0,48)||'EMBER-01';const r={version:VERSION,id:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,seed,mode,rng:hash(seed),startedAt:Date.now(),stage:0,phase:'battle',hp:70,maxHp:70,deck:[...Array(5).fill('strike'),...Array(4).fill('defend'),'spark'].map(id=>({id,up:false})),relics:['core'],log:[],events:[],stats:{cardsPlayed:0,turns:0,damageDealt:0,damageTaken:0,battlesWon:0},rewardHistory:[],rating:null};track(r,'start',{seed,mode});startStage(r);return r;}
function startStage(r){const s=STAGES[r.stage];r.phase=s.type;r.log=[];if(s.type==='battle'){r.enemy={...structuredClone(ENEMIES[s.enemy]),hp:ENEMIES[s.enemy].maxHp,block:0,str:0,poison:0,vulnerable:0,step:0};r.rng=hash(`${r.seed}:combat:${r.stage}`);r.draw=shuffle(r,r.deck.map(c=>({...c})));r.hand=[];r.discard=[];r.exhaust=[];r.str=0;r.block=0;r.turn=0;newTurn(r);log(r,`${r.enemy.name} 阻断了通往核心的道路。`);}track(r,'stage',{kind:s.type});}
function newTurn(r){r.turn++;r.stats.turns++;r.energy=r.turn===1?4:3;r.block=0;draw(r,5);log(r,`第 ${r.turn} 回合 · ${r.energy} 能量`);}
function heal(r,n){const a=Math.min(n,r.maxHp-r.hp);r.hp+=a;return a;}
function hitEnemy(r,amount,pierce=false){const blocked=pierce?0:Math.min(r.enemy.block,amount);r.enemy.block-=blocked;const dealt=Math.min(r.enemy.hp,Math.max(0,amount-blocked));r.enemy.hp-=dealt;r.stats.damageDealt+=dealt;return dealt;}
function endRun(r,result){r.phase='ended';r.result=result;r.endedAt=Date.now();r.durationMs=r.endedAt-r.startedAt;track(r,'end',{result});log(r,result==='win'?'核心已重启。余烬仍在，新的可能已经出现。':'信号中断。这次选择会成为下一次重来的经验。',result==='win'?'good':'bad');}
function checkBattle(r){if(r.hp<=0){endRun(r,'loss');return true;}if(r.enemy.hp<=0){r.stats.battlesWon++;track(r,'battle_won',{turns:r.turn,hp:r.hp});if(r.relics.includes('seal'))heal(r,4);if(r.stage===6){endRun(r,'win');return true;}if(r.stage===4){r.relics.push('seal');log(r,'获得遗物：焚心印记，此后战斗胜利回复 4 点生命。','good');}const rr={rng:hash(`${r.seed}:reward:${r.stage}`)};r.offers=shuffle(rr,POOL).slice(0,3).map(id=>({id,up:false}));r.phase='reward';track(r,'reward_offered',{offers:r.offers.map(c=>c.id)});return true;}return false;}
export function playCard(r,index){if(r.phase!=='battle'||!Number.isInteger(index)||!r.hand[index])return false;const c=r.hand[index],d=cardData(c);if(d.cost>r.energy)return false;r.energy-=d.cost;r.hand.splice(index,1);(d.exhaust?r.exhaust:r.discard).push(c);let total=0;if(d.dmg){let base=d.dmg;if(d.finisher&&r.enemy.hp<=r.enemy.maxHp/2)base*=2;for(let k=0;k<(d.hits||1);k++)total+=hitEnemy(r,Math.floor((base+r.str)*(r.enemy.vulnerable>0?1.5:1)),d.pierce);}if(d.block)r.block+=d.block;if(d.heal)heal(r,d.heal);if(d.poison)r.enemy.poison+=d.poison;if(d.vulnerable)r.enemy.vulnerable+=d.vulnerable;if(d.str)r.str+=d.str;if(d.energy)r.energy+=d.energy;if(d.draw)draw(r,d.draw);r.stats.cardsPlayed++;track(r,'card_played',{card:c.id,up:c.up,damage:total});log(r,`${d.name}${c.up?'+':''}${total?` · 造成 ${total} 点伤害`:''}${d.block?` · 护盾 +${d.block}`:''}${d.poison?` · 腐蚀 +${d.poison}`:''}`,'good');checkBattle(r);return true;}
export function endTurn(r){if(r.phase!=='battle')return false;r.discard.push(...r.hand);r.hand=[];r.enemy.block=0;if(r.enemy.poison>0){const n=hitEnemy(r,r.enemy.poison,true);r.enemy.poison--;log(r,`腐蚀造成 ${n} 点伤害。`,'good');if(checkBattle(r))return true;}const it=intent(r);if(it.type==='attack'){let loss=0;for(let k=0;k<(it.hits||1);k++){const n=it.value+r.enemy.str,b=Math.min(r.block,n);r.block-=b;const damage=Math.min(r.hp,n-b);r.hp-=damage;loss+=damage;}r.stats.damageTaken+=loss;log(r,`${r.enemy.name} 发动攻击 · 失去 ${loss} 点生命。`,loss?'bad':'info');}else if(it.type==='guard'){r.enemy.block=it.value;log(r,`敌人获得 ${it.value} 点护盾。`);}else{r.enemy.str+=it.value;log(r,`敌人力量 +${it.value}。`,'bad');}r.enemy.vulnerable=Math.max(0,r.enemy.vulnerable-1);r.enemy.step++;if(!checkBattle(r))newTurn(r);return true;}
export function takeReward(r,index=0){if(r.phase!=='reward')return false;const i=r.mode==='random'?0:index;if(!Number.isInteger(i)||!r.offers[i])return false;const c={...r.offers[i]};r.deck.push(c);r.rewardHistory.push({stage:r.stage+1,offers:r.offers.map(x=>x.id),selected:c.id,mode:r.mode});track(r,'reward_taken',{card:c.id,index:i});r.phase='travel';return true;}
export function advance(r){if(r.phase!=='travel'||r.stage>=6)return false;r.stage++;startStage(r);return true;}
export function eventChoice(r,choice,cardIndex){if(r.phase!=='event')return false;if(r.stage===1){if(choice==='repair'){heal(r,10);}else if(choice==='risk'){r.hp=Math.max(1,r.hp-5);r.deck.push({id:'ignite',up:false});}else return false;}else if(r.stage===5){if(choice==='repair'){heal(r,14);}else if(choice==='remove'){if(!Number.isInteger(cardIndex)||!r.deck[cardIndex]||r.deck.length<=5)return false;const [c]=r.deck.splice(cardIndex,1);track(r,'remove',{card:c.id});}else return false;}track(r,'event_choice',{choice});r.phase='travel';return true;}
export function camp(r,choice,index){if(r.phase!=='camp')return false;if(choice==='rest')heal(r,22);else if(choice==='upgrade'){if(!Number.isInteger(index)||!r.deck[index]||r.deck[index].up)return false;r.deck[index].up=true;track(r,'upgrade',{card:r.deck[index].id});}else return false;track(r,'camp',{choice});r.phase='travel';return true;}
export function abandon(r){if(!r||r.phase==='ended')return false;endRun(r,'abandoned');return true;}
export function validRun(r){return r&&r.version===VERSION&&['choice','random'].includes(r.mode)&&typeof r.id==='string'&&typeof r.seed==='string'&&Number.isFinite(r.hp)&&r.hp>=0&&r.hp<=70&&r.maxHp===70&&Number.isInteger(r.stage)&&r.stage>=0&&r.stage<7&&['battle','reward','travel','event','camp','ended'].includes(r.phase)&&Array.isArray(r.deck)&&r.deck.length>=5&&r.deck.length<=30&&r.deck.every(c=>CARDS[c.id]&&typeof c.up==='boolean')&&r.stats&&Array.isArray(r.events)&&Array.isArray(r.log)&&(r.phase!=='battle'||(r.enemy&&r.enemy.intents?.length&&Array.isArray(r.hand)&&Array.isArray(r.draw)&&Array.isArray(r.discard)&&Array.isArray(r.exhaust)));}
